   ```javascript
   const { Client, GatewayIntentBits, Events, SlashCommandBuilder } = require('discord.js');
   const { Routes } = require('@discordjs/rest');

   const client = new Client({
     intents: [
       GatewayIntentBits.Guilds,
       GatewayIntentBits.GuildMessages,
       GatewayIntentBits.MessageContent,
     ],
   });

   const commands = [
     new SlashCommandBuilder()
       .setName('ban')
       .setDescription('Bans a user from the server.')
       .addUserOption((option) =>
         option
           .setName('user')
           .setDescription('The user to ban.')
           .setRequired(true)
       )
       .addStringOption((option) =>
         option
           .setName('reason')
           .setDescription('The reason for the ban.')
           .setRequired(false)
       ),
   ];

   const rest = new REST({ version: '9' }).setToken(process.env.DISCORD_TOKEN);

   async function registerCommands() {
     try {
       await rest.put(Routes.applicationCommands(process.env.APPLICATION_ID), { body: commands });
       console.log('Successfully registered application commands.');
     } catch (error) {
       console.error(error);
     }
   }

   async function run() {
     try {
       await registerCommands();

       client.on(Events.InteractionCreate, async (interaction) => {
         if (!interaction.isCommand()) return;

         const { commandName, options } = interaction;

         if (commandName === 'ban') {
           const user = options.getMember('user');
           const reason = options.getString('reason') || 'No reason provided';

           if (!user) {
             return interaction.reply({ content: 'Unable to find user to ban.', ephemeral: true });
           }

           await user.ban({ reason });

           return interaction.reply({ content: `${user.user.tag} has been banned. Reason: ${reason}`, ephemeral: false });
         }
       });

       await client.login(process.env.DISCORD_TOKEN);
     } catch (error) {
       console.error(error);
     }
   }

   run();
   ```

