```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <boost/algorithm/string.hpp>

// Map of Markdown syntax to HTML tags
const std::unordered_map<std::string, std::string> markdown_to_html{
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"* ", "<em>"},
    {"** ", "<strong>"},
    {"~~ ", "<del>"},
    {"` ", "<code>"},
    {"[ ](", "<a href=\"\">"),
    {"](", "\")"},
    {"< ", "&lt;"},
    {">", "&gt;"},
    {"\n", "<br>"}
};

std::string convertMarkdownToHTML(std::string& markdown) {
    std::string html;

    // Loop through each line of the Markdown text
    for (const auto& line : boost::split(markdown, "\n")) {
        // Loop through each word in the line
        for (const auto& word : boost::split(line, " ")) {
            // Check if the word is a Markdown syntax
            if (auto it = markdown_to_html.find(word); it != markdown_to_html.end()) {
                // Replace the Markdown syntax with its corresponding HTML tag
                html += it->second;
            } else {
                // Append the word as plain text
                html += word;
            }
        }
        // Append a line break after each Markdown line
        html += "<br>";
    }

    // Remove the last line break
    html.pop_back();

    return html;
}

int main() {
    std::string markdown = "# Hello World\n"
                           "This is a **bold** text with a [link](https://example.com/).";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses the Boost library's `split` function to split the input Markdown text into lines and words, and then loops through each word to check for Markdown syntax. If a Markdown syntax is found, its corresponding HTML tag is appended to the output HTML string. Otherwise, the word is appended as plain text. A line break is also appended after each Markdown line, and the last line break is removed from the output HTML string.

